function evFlush(){if(evBusy)return;const q=evQueue();if(!q.length)return;evBusy=true;const batch=q.slice(0,25);fetch(EV_URL,{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','apikey':EV_KEY,'Authorization':'Bearer '+EV_KEY,'Prefer':'return=minimal'},body:JSON.stringify(batch)}).then(r=>{if(r.ok||r.status===400||r.status===404){try{sessionStorage.setItem('codem-ev',JSON.stringify(evQueue().slice(batch.length)));}catch{}}}).catch(()=>{}).finally(()=>{evBusy=false;if(evQueue().length&&evQueue().length<200)evTimer=setTimeout(evFlush,4000);});}
