function fieldLabel(el){return (el.closest('.field')?.querySelector('label')?.textContent||el.closest('label')?.textContent||el.name||'').replace(/\s*\*\s*$/,'').trim();}
function setError(el,msg){el.setAttribute('aria-invalid',msg?'true':'false');const err=el.closest('.field')?.querySelector('.field-error')||document.getElementById(el.name+'-error');if(err)err.textContent=msg||'';}
function validate(scope){const problems=[];const seen=new Set();scope.querySelectorAll('input,select,textarea').forEach(el=>{if(el.disabled||el.closest('[hidden]')||el.type==='hidden'||el.name==='website')return;if(el.type==='file'){const m=fileProblem(el);setError(el,m);if(m)problems.push({el,label:fieldLabel(el),msg:m});return;}if(el.type==='radio'){if(!el.required||seen.has(el.name))return;seen.add(el.name);if(!scope.querySelector(`[name="${el.name}"]:checked`)){const m=tr('Choisissez une option.','Please choose an option.');setError(el,m);problems.push({el,label:el.closest('fieldset')?.querySelector('legend')?.textContent||el.name,msg:m});}else setError(el,'');return;}if(el.type==='checkbox'){if(el.required&&!el.checked){const m=tr('Cette case doit être cochée.','This box must be ticked.');setError(el,m);problems.push({el,label:fieldLabel(el),msg:m});}else if(el.required)setError(el,'');return;}if(el.type==='tel'){const v=el.value.trim();el.setCustomValidity(v&&(/[^0-9+().\s-]/.test(v)||v.replace(/\D/g,'').length<9)?'tel':'');}const ok=el.checkValidity();const m=ok?'':el.type==='tel'&&!el.validity.valueMissing?tr('Indiquez un numéro de téléphone valide (chiffres uniquement).','Enter a valid phone number (digits only).'):el.validity.valueMissing?tr('Veuillez compléter ce champ.','Please complete this field.'):tr('Veuillez vérifier cette information.','Please check this information.');setError(el,m);if(!ok)problems.push({el,label:fieldLabel(el),msg:m});});return problems;}
function contactRule(form,problems){const email=form.querySelector('[name="email"]'),tel=form.querySelector('[name="telephone"]'),canal=form.querySelector('[name="canal"],[name="preference"]');if(!email||!tel)return problems;const want=canal?.value;if(!email.value.trim()&&!tel.value.trim()){const m=tr('Indiquez un e-mail ou un téléphone.','Enter an email or a phone number.');setError(tel,m);problems.push({el:tel,label:fieldLabel(tel),msg:m});}else if(want==='email'&&!email.value.trim()){const m=tr('Indiquez votre e-mail.','Enter your email.');setError(email,m);problems.push({el:email,label:fieldLabel(email),msg:m});}else if(want==='telephone'&&!tel.value.trim()){const m=tr('Indiquez votre téléphone.','Enter your phone number.');setError(tel,m);problems.push({el:tel,label:fieldLabel(tel),msg:m});}return problems;}
