const MAX_FILES=8,MAX_MB=25;
function fileProblem(input){const fs=[...(input?.files||[])];if(fs.length>MAX_FILES)return tr(`${MAX_FILES} fichiers maximum.`,`${MAX_FILES} files maximum.`);const big=fs.find(f=>f.size>MAX_MB*1048576);if(big)return tr(`« ${big.name} » dépasse ${MAX_MB} Mo.`,`"${big.name}" is larger than ${MAX_MB} MB.`);const bad=fs.find(f=>!/^(image|video)\//.test(f.type));if(bad)return tr(`« ${bad.name} » n’est ni une photo ni une vidéo.`,`"${bad.name}" is not a photo or video.`);return '';}
