async function uploadFiles(ep,files,ref){const base=ep.replace(/\/rest\/v1\/.*$/,'')+'/storage/v1/object/devis-photos/';const folder=(ref||'sans-ref')+'-'+Math.random().toString(36).slice(2,8);const ok=[],failed=[];let i=0;for(const f of files){i++;const name=f.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9._-]+/g,'-').slice(-60)||'fichier';const path=`${folder}/${i}-${name}`;try{const r=await fetch(base+path,{method:'POST',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':f.type||'application/octet-stream','x-upsert':'false'},body:f});if(!r.ok)throw 0;ok.push(path);}catch{failed.push(f.name);}}return {ok,failed};}
